INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('home', 'place', '«إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللَّهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ»', 'Wie zijn huis binnentreedt en Allaah gedenkt bij het binnenkomen en bij zijn eten, ontzegt de shaytaan overnachting en avondmaal in zijn huis.', 'Whoever enters his home mentioning Allaah upon entering and at his food denies Satan lodging and supper in his house.', '', '', '', 'الأجر مبين: حرمان الشيطان من المبيت والعشاء في بيته.', 'De beloning is toegelicht: het ontzeggen aan de shaytaan van overnachting en avondmaal in zijn huis.', 'The reward is explained: denying Satan lodging and supper in his house.', 'وإذا دخل بيته ذكر الله عند دخوله وعند طعامه', 'plaats', 'place', 1, 141),('home', 'place', '﴿فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا عَلَى أَنفُسِكُمْ تَحِيَّةً مِّنْ عِندِ اللَّهِ مُبَارَكَةً طَيِّبَةً﴾', 'Wanneer jullie dan huizen binnentreden, groet dan elkaar met een groet van bij Allaah, gezegend en goed.', '', 'يسلّم الداخل على أهل بيته، فإن لم يكن فيه أحد فظاهر الآية عمومها؛ فيجمع الداخل: التسمية والذكر ثم السلام.', 'De binnentredende groet zijn huisgenoten; is er niemand, dan geldt de algemeenheid van het vers; de binnentredende combineert dus tasmiyah, dhikr en groet.', 'The one entering greets his household; if none is there, the generality of the verse applies; so the one entering combines tasmiyah, dhikr and greeting.', 'وصفها الله بأنها تحية من عنده مباركة طيبة.', 'Allaah beschreef haar als een groet van bij Hem, gezegend en goed.', 'Allaah described it as a greeting from Him, blessed and good.', 'التسليم عند دخول البيت', 'plaats', 'place', 1, 142),('toilet', 'place', '«بِسْمِ اللَّهِ»؛ فَإِنَّهَا سِتْرُ مَا بَيْنَ أَعْيُنِ الْجِنِّ وَعَوْرَاتِ بَنِي آدَمَ', 'In de Naam van Allaah — de afscherming tussen de ogen van de djinn en de 3awrah van de mens bij het betreden van het toilet.', 'In the Name of Allaah — the screen between the eyes of the jinn and man''s nakedness upon entering the lavatory.', '', '', '', 'الأجر منصوص: ستر عن أعين الجن.', 'De beloning is uitdrukkelijk: een afscherming voor de ogen van de djinn.', 'The reward is stated: a screen from the eyes of the jinn.', 'عند دخول الخلاء', 'plaats', 'place', 1, 143),('toilet', 'place', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ»', 'O Allaah, ik zoek toevlucht bij U tegen de mannelijke en de vrouwelijke shayaatien.', 'O Allaah, I seek refuge in You from the male and female devils.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ثم يقول', 'plaats', 'place', 1, 144),('toilet', 'place', '«غُفْرَانَكَ»', '(Ik vraag om) Uw vergeving.', '(I ask for) Your forgiveness.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند الخروج من الخلاء', 'plaats', 'place', 1, 145),('mosque', 'event', '«اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ بَيْنِ يَدَيَّ نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا»', 'O Allaah, plaats licht in mijn hart, licht op mijn tong, licht in mijn gehoor, licht in mijn zicht, licht achter mij, licht vóór mij, licht boven mij en licht onder mij. O Allaah, schenk mij licht.', 'O Allaah, place light in my heart, light on my tongue, light in my hearing, light in my sight, light behind me, light before me, light above me and light beneath me. O Allaah, grant me light.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء الذهاب إلى المسجد', 'plaats', 'place', 1, 146),('mosque', 'event', '«أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ»', 'Ik zoek toevlucht bij Allaah, de Geweldige, bij Zijn edele Aangezicht en Zijn eeuwige heerschappij, tegen de vervloekte shaytaan.', 'I seek refuge in Allaah the Magnificent, in His Noble Face and His eternal authority, from the accursed devil.', '', '', '', 'الأجر منصوص: يقول الشيطان: حُفظ مني سائر اليوم.', 'De beloning is uitdrukkelijk: de shaytaan zegt: ik ben tegen hem beschermd de rest van de dag.', 'The reward is stated: Satan says: I am kept from him the rest of the day.', 'وإذا دخل المسجد قدّم رجله اليمنى وقال', 'plaats', 'place', 1, 147),('mosque', 'event', '«اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ»', 'O Allaah, open voor mij de poorten van Uw barmhartigheid.', 'O Allaah, open for me the gates of Your mercy.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند دخول المسجد', 'plaats', 'place', 1, 148),('mosque', 'event', '«اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ»', 'O Allaah, ik vraag U om Uw gunst.', 'O Allaah, I ask You of Your bounty.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا خرج قدّم رجله اليسرى وقال', 'plaats', 'place', 1, 149),('mosque', 'event', '«اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ»', 'O Allaah, bescherm mij tegen de vervloekte shaytaan.', 'O Allaah, protect me from the accursed devil.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ويزيد', 'plaats', 'place', 1, 150),('market', 'place', '«لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ»', 'De tahliel van de markt: niets of niemand heeft het recht aanbeden te worden behalve Allaah (tawhied), alleen, zonder deelgenoot; aan Hem de heerschappij en de lof; Hij geeft leven en doet sterven terwijl Hij de al-Levende (al-Hayy) is Die niet sterft; in Zijn Hand is al het goede, en Hij is tot alles in staat — met een miljoen hasanaat als beloning.', 'The market tahleel: none has the right to be worshipped except Allaah alone, without partner; His is the dominion and praise; He gives life and causes death while He is al-Hayy (the Ever-Living) and dies not; in His Hand is all good, and He is able to do all things — rewarded with a million hasanaat.', '', '', '', 'الأجر منصوص: ألف ألف حسنة، ومحو ألف ألف سيئة، ورفع ألف ألف درجة، وفي رواية: بيت في الجنة.', 'De beloning is uitdrukkelijk: een miljoen goede daden, het wissen van een miljoen zonden, het verheffen van een miljoen rangen, en in een overlevering: een huis in het Paradijs.', 'The reward is stated: a million good deeds, the erasing of a million sins, the raising of a million ranks, and in one narration: a house in Paradise.', 'التهليل عند دخول السوق', 'plaats', 'place', 1, 151),('travel_route', 'place', '«أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ»', 'Wie bij het betrekken van een verblijfplaats zegt: ik zoek toevlucht bij de volmaakte Woorden van Allaah tegen het kwade van wat Hij heeft geschapen — niets zal hem schaden totdat hij weer vertrekt.', 'Whoever, upon alighting at a stopping-place, says: I seek refuge in the perfect Words of Allaah from the evil of what He created — nothing will harm him until he departs from it.', '', '', '', 'الأجر منصوص: لا يضره شيء حتى يرتحل.', 'De beloning is uitdrukkelijk: niets zal hem schaden tot hij weer vertrekt.', 'The reward is stated: nothing will harm him until he departs.', 'عند نزول منزل في السفر', 'plaats', 'place', 1, 152),('travel_route', 'place', '«كُنَّا إِذَا صَعِدْنَا كَبَّرْنَا، وَإِذَا نَزَلْنَا سَبَّحْنَا»', 'Bij het omhooggaan zeiden wij: Allaah is de Grootste; en bij het afdalen: Verheven is Allaah.', 'When ascending we said: Allaah is the Greatest; and when descending: Glory be to Allaah.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التكبير عند صعود الثنايا والتسبيح عند الهبوط', 'plaats', 'place', 1, 153),('travel_route', 'place', '«سَمَّعَ سَامِعٌ بِحَمْدِ اللَّهِ وَحُسْنِ بَلَائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا وَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللَّهِ مِنَ النَّارِ»', 'Moge een getuige overbrengen dat wij Allaah loven voor Zijn goede gunsten aan ons. Onze Heer, vergezel ons en begunstig ons — toevlucht zoekend bij Allaah tegen het Vuur.', 'May a witness convey our praise of Allaah for His good favours upon us. Our Lord, accompany us and bestow favour upon us — seeking refuge in Allaah from the Fire.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا كان في السحَر من سفره قال', 'plaats', 'place', 1, 154),('entering_town', 'place', '«اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الْأَرَضِينَ السَّبْعِ وَمَا أَقْلَلْنَ، وَرَبَّ الشَّيَاطِينِ وَمَا أَضْلَلْنَ، وَرَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ: أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ وَخَيْرَ أَهْلِهَا وَخَيْرَ مَا فِيهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وَشَرِّ مَا فِيهَا»', 'O Allaah, Heer van de zeven hemelen en wat zij overschaduwen, Heer van de zeven aarden en wat zij dragen, Heer van de shayaatien en wie zij misleiden, Heer van de winden en wat zij verstrooien: ik vraag U het goede van deze plaats, het goede van haar bewoners en het goede van wat zich erin bevindt, en ik zoek toevlucht bij U tegen haar kwaad, het kwaad van haar bewoners en het kwaad van wat zich erin bevindt.', 'O Allaah, Lord of the seven heavens and what they shade, Lord of the seven earths and what they carry, Lord of the devils and whom they lead astray, Lord of the winds and what they scatter: I ask You for the good of this town, the good of its people and the good of what is in it, and I seek refuge in You from its evil, the evil of its people and the evil of what is in it.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند دخول قرية أو بلدة', 'plaats', 'place', 1, 155),('graveyard', 'place', '«السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ»', 'Vrede zij met jullie, bewoners van deze verblijfplaatsen, gelovigen en moslims. Waarlijk, wij zullen ons — als Allaah het wil — bij jullie voegen. Ik vraag Allaah om welzijn voor ons en voor jullie.', 'Peace be upon you, people of these abodes, believers and Muslims. Indeed, if Allaah wills, we shall join you. I ask Allaah for wellbeing for us and for you.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء زيارة القبور', 'plaats', 'place', 1, 156),('graveyard', 'place', 'يخلع نعليه إذا مشى بين القبور ــ إلا من عذر كشوك وحرّ ــ مع سلام الزيارة المتقدم', 'Men trekt zijn schoenen uit wanneer men tussen de graven loopt — behalve bij een excuus zoals doornen of hitte — samen met de groet van het bezoek.', 'One removes one''s sandals when walking between the graves — except for an excuse such as thorns or heat — along with the greeting of visiting.', 'الخلع للمشي بين القبور نفسها، لا لمجرد دخول المقبرة وطرقها.', 'Het uittrekken geldt voor het lopen tussen de graven zelf, niet voor het enkel betreden van de begraafplaats en haar paden.', 'The removal applies to walking between the graves themselves, not to merely entering the graveyard and its paths.', 'لم يرد فيه أجر مخصوص، وفيه توقير حرمة الموتى.', 'Er is geen specifieke beloning voor overgeleverd, daarin ligt de eerbiediging van de heiligheid van de doden.', 'No specific reward is reported, in it is honouring the sanctity of the dead.', 'ومن هيئة المشي بين القبور', 'plaats', 'place', 1, 157),('clothing', 'life', '«الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ»', 'Alle lof zij Allaah, Die mij dit kledingstuk heeft aangekleed en mij ervan heeft voorzien, zonder enige macht of kracht van mijn kant.', 'All praise is for Allaah who clothed me with this garment and provided it for me without any might or power on my part.', '', '', '', 'الأجر منصوص: «غُفر له ما تقدم من ذنبه».', 'De beloning is uitdrukkelijk: ''zijn voorgaande zonden worden hem vergeven''.', 'The reward is stated: ''his past sins are forgiven him''.', 'عند لبس الثوب', 'toestand', 'state/situation', 1, 158),('clothing', 'life', '«اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ»', 'O Allaah, aan U alle lof: U heeft mij hiermee gekleed. Ik vraag U om het goede ervan en het goede waarvoor het gemaakt is, en ik zoek toevlucht bij U tegen het kwade ervan en het kwade waarvoor het gemaakt is.', 'O Allaah, to You is all praise: You have clothed me with it. I ask You for its good and the good for which it was made, and I seek refuge in You from its evil and the evil for which it was made.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا استجد ثوبا سماه باسمه ثم قال', 'toestand', 'state/situation', 1, 159),('clothing', 'life', '«أَبْلِي وَأَخْلِقِي»', 'Draag het tot het verslijt en versleten raakt — een smeekbede om een lang leven.', 'Wear it out and wear it to shreds — a supplication for long life.', '', '', '', 'دعاء بطول العمر حتى تبلى الثياب وتخلق.', 'Een smeekbede om een lang leven, tot de kleding verslijt en versleten raakt.', 'A supplication for long life, until the garment wears out and is worn to shreds.', 'الدعاء للابس الجديد', 'toestand', 'state/situation', 1, 160);